<?php
if (!defined("SUAVE_RAIZ")) { http_response_code(404); exit; } use Suave\Interfaz as V;
$products=$db->all('SELECT * FROM productos ORDER BY activo DESC,nombre');
$editBranch=isset($_GET['editar_sucursal'])?$db->one('SELECT * FROM sucursales WHERE codigo=?',[(string)$_GET['editar_sucursal']]):null;
$editProduct=isset($_GET['editar_producto'])?$db->one('SELECT * FROM productos WHERE nombre=?',[(string)$_GET['editar_producto']]):null;
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['tipo']??'')==='sucursal')$editBranch=array_replace($editBranch??[],$_POST);
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['tipo']??'')==='producto')$editProduct=array_replace($editProduct??[],$_POST);
?>
<div class="page-heading"><div><h1>Sucursales y productos</h1><p>Dos listas breves dentro del mismo módulo.</p></div></div>
<div class="columns catalogs">
<section><h2>Sucursales</h2><div class="table-wrap"><table><thead><tr><th>Sucursal</th><th>Nombre</th><th>Acción</th></tr></thead><tbody><?php foreach($allBranches as $b):?><tr><td><strong><?=V::h($b['codigo'])?></strong></td><td><?=V::h($b['nombre'])?><?php if(!$b['activo']):?><small>Fuera de uso</small><?php endif?></td><td><?=$w->link('Editar','catalogos',['editar_sucursal'=>$b['codigo']],'text-link')?></td></tr><?php endforeach?><?php if(!$allBranches):?><tr><td colspan="3" class="empty-cell">Registra tu primera sucursal.</td></tr><?php endif?></tbody></table></div>
<div class="action-row"><?=$w->link('+ Nueva sucursal','catalogos',['editar_producto'=>$editProduct['original']??$editProduct['nombre']??null])?></div>
<form method="post" data-dirty class="catalog-form"><?=V::protect('catalogo_guardar')?><?=V::hidden('tipo','sucursal')?><?=V::hidden('original',$editBranch['original']??$editBranch['codigo']??'')?><?=V::hidden('revision',$editBranch['revision']??0)?><?=V::hidden('activo',$editBranch['activo']??1)?>
<div class="form-grid"><?=V::input('Código de sucursal *','codigo',$editBranch['codigo']??'','text',['maxlength'=>32,'required'=>true,'readonly'=>!empty($editBranch['original']??$editBranch['codigo']??'')])?><?=V::input('Nombre de sucursal *','nombre',$editBranch['nombre']??'','text',['maxlength'=>160,'required'=>true])?></div><div class="action-row"><button class="button primary" type="submit">Guardar sucursal</button></div></form>
<?php if(!empty($editBranch['original']??$editBranch['codigo']??'')):?><form method="post" data-confirm="<?=V::h(($editBranch['activo']??1)?'¿Dejar de usar esta sucursal en nuevas capturas? Su historial se conservará.':'¿Volver a usar esta sucursal?')?>"><?=V::protect('catalogo_guardar')?><?=V::hidden('tipo','sucursal')?><?=V::hidden('original',$editBranch['original']??$editBranch['codigo'])?><?=V::hidden('codigo',$editBranch['codigo'])?><?=V::hidden('nombre',$editBranch['nombre'])?><?=V::hidden('revision',$editBranch['revision'])?><?=V::hidden('activo',empty($editBranch['activo'])?1:0)?><button class="button" type="submit"><?=empty($editBranch['activo'])?'Volver a usar':'Dejar de usar'?></button></form><?php endif?>
</section>
<section><h2>Productos por nombre</h2><div class="table-wrap"><table><thead><tr><th>Nombre del producto</th><th>Acción</th></tr></thead><tbody><?php foreach($products as $product):?><tr><td><?=V::h($product['nombre'])?><?php if(!$product['activo']):?><small>Fuera de uso</small><?php endif?></td><td><?=$w->link('Editar','catalogos',['editar_producto'=>$product['nombre']],'text-link')?></td></tr><?php endforeach?><?php if(!$products):?><tr><td colspan="2" class="empty-cell">Registra el primer producto por su nombre.</td></tr><?php endif?></tbody></table></div>
<div class="action-row"><?=$w->link('+ Nuevo producto','catalogos',['editar_sucursal'=>$editBranch['codigo']??null])?></div>
<form method="post" data-dirty class="catalog-form"><?=V::protect('catalogo_guardar')?><?=V::hidden('tipo','producto')?><?=V::hidden('original',$editProduct['original']??$editProduct['nombre']??'')?><?=V::hidden('revision',$editProduct['revision']??0)?><?=V::hidden('activo',$editProduct['activo']??1)?><?=V::input('Nombre del producto *','nombre',$editProduct['nombre']??'','text',['maxlength'=>160,'required'=>true])?><div class="action-row"><button class="button primary" type="submit">Guardar producto</button></div></form>
<?php if(!empty($editProduct['original']??$editProduct['nombre']??'')):?><form method="post" data-confirm="<?=V::h(($editProduct['activo']??1)?'¿Dejar de usar este producto en nuevas capturas? Las notas anteriores se conservarán.':'¿Volver a usar este producto?')?>"><?=V::protect('catalogo_guardar')?><?=V::hidden('tipo','producto')?><?=V::hidden('original',$editProduct['original']??$editProduct['nombre'])?><?=V::hidden('nombre',$editProduct['nombre'])?><?=V::hidden('revision',$editProduct['revision'])?><?=V::hidden('activo',empty($editProduct['activo'])?1:0)?><button class="button" type="submit"><?=empty($editProduct['activo'])?'Volver a usar':'Dejar de usar'?></button></form><?php endif?>
</section></div><p class="hint">Cada entrega conserva su propio nombre histórico, cantidad y precio. Dejar de usar un catálogo conserva los documentos anteriores.</p>
